namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _all = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed initial fake data.
        _all.AddRange(new[]
        {
            MakeNotification("Welcome to the app!"),
            MakeNotification("Your profile was updated."),
            MakeNotification("You have a new follower."),
        });
    }

    /// <summary>Returns every notification created so far.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock) return _all.ToList();
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock) return _all.Where(n => n.Id > lastSeenId).ToList();
    }

    /// <summary>
    /// Simulates external activity by occasionally adding a notification.
    /// Called by the polling loop so there is something new to discover.
    /// </summary>
    public void SimulateActivity()
    {
        // ~30 % chance each tick
        if (Random.Shared.Next(0, 10) < 3)
        {
            lock (_lock)
            {
                _all.Add(MakeNotification($"Event #{_nextId} happened."));
            }
        }
    }

    private Notification MakeNotification(string message)
    {
        var n = new Notification(_nextId, message, DateTime.UtcNow);
        _nextId++;
        return n;
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IAsyncDisposable
@using NotificationsApp.Services
@inject NotificationService Svc
@inject PersistentComponentState PersistState

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;
    private int _lastSeenId;

    protected override void OnInitialized()
    {
        // Subscribe so we can persist state before the page goes interactive.
        _persistSub = PersistState.RegisterOnPersisting(PersistNotifications);

        // Try to restore data that was persisted during SSR.
        if (PersistState.TryTakeFromJson<List<Notification>>(
                "notifications", out var restored) && restored is not null)
        {
            _notifications = restored;
            _lastSeenId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;
        }
        else
        {
            // First (SSR) render — load from the service.
            _notifications = Svc.GetAll();
            _lastSeenId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender only fires when the component is live in the
        // browser, so the polling loop never runs during static SSR.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Let the service simulate some external activity.
            Svc.SimulateActivity();

            var newer = Svc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    private Task PersistNotifications()
    {
        PersistState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

