namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _all = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed initial fake data.
        _all.AddRange(new[]
        {
            MakeNotification("Welcome to the app!"),
            MakeNotification("Your profile was updated."),
            MakeNotification("You have a new follower."),
        });
    }

    /// <summary>Returns every notification created so far.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock) return _all.ToList();
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock) return _all.Where(n => n.Id > lastSeenId).ToList();
    }

    /// <summary>
    /// Simulates external activity by occasionally adding a notification.
    /// Called by the polling loop so there is something new to discover.
    /// </summary>
    public void SimulateActivity()
    {
        // ~30 % chance each tick
        if (Random.Shared.Next(0, 10) < 3)
        {
            lock (_lock)
            {
                _all.Add(MakeNotification($"Event #{_nextId} happened."));
            }
        }
    }

    private Notification MakeNotification(string message)
    {
        var n = new Notification(_nextId, message, DateTime.UtcNow);
        _nextId++;
        return n;
    }
}

